CREATE TABLE IF NOT EXISTS "games_test" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"creator_id" INTEGER NOT NULL,
	"game_code" VARCHAR(255) NOT NULL UNIQUE,
	"start_stage_id" INTEGER,
	"name" VARCHAR(255),
	"description" TEXT,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "stages_test" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"game_id" INTEGER NOT NULL,
    "name" VARCHAR(255),
	"lon" DECIMAL CHECK(("lon" IS NULL OR "lon" BETWEEN -180 AND 180)),
	"lat" DECIMAL CHECK(("lat" IS NULL OR "lat" BETWEEN -90 AND 90)),
	"qrcode_uid" VARCHAR(255),
	"determine_range" DECIMAL CHECK(("determine_range" IS NULL OR "determine_range" >= 0)),
	"limit_seconds" INTEGER CHECK(("limit_seconds" IS NULL OR "limit_seconds" >= 0)),
	"quest" JSONB,
	"is_end" BOOLEAN NOT NULL DEFAULT FALSE,
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT NOW(),
	PRIMARY KEY("id")
);

CREATE TABLE IF NOT EXISTS "game_play_stages_test" (
	"id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
	"gameplay_id" INTEGER NOT NULL,
	"now_stage_id" INTEGER NOT NULL,
	"next_stage_id" INTEGER,
	"checked_at" TIMESTAMPTZ,
	"lon" DECIMAL CHECK(("lon" IS NULL OR "lon" BETWEEN -180 AND 180)),
	"lat" DECIMAL CHECK(("lat" IS NULL OR "lat" BETWEEN -90 AND 90)),
	"start_at" TIMESTAMPTZ NOT NULL,
	PRIMARY KEY("id")
);
